"""Claim result formatting."""
from datetime import datetime, timezone
from typing import Dict, Any, List

DISCLAIMER = (
    "This output is generated by a fraud-risk decision-support prototype for academic purposes. "
    "It is NOT a final legal, medical, or insurance determination. "
    "A qualified human reviewer must remain involved, especially for REJECT_OR_ESCALATE or high-impact claims."
)

def format_claim_result(
    claim_id: str,
    model_version: str,
    fraud_probability: float,
    fraud_prediction: int,
    anomaly_score: float,
    document_validation_status: str,
    policy_validation_status: str,
    risk_category: str,
    recommended_decision: str,
    key_risk_signals: List[str],
    positive_evidence: List[str],
    missing_or_inconsistent_info: List[str],
    explanation: str,
    evidence_references: List[Dict[str, Any]],
    extra: Dict[str, Any] = None
) -> Dict[str, Any]:
    result = {
        "claim_id": claim_id,
        "model_version": model_version,
        "fraud_probability": round(float(fraud_probability), 4),
        "fraud_prediction": int(fraud_prediction),
        "anomaly_score": float(anomaly_score),
        "document_validation_status": document_validation_status,
        "policy_validation_status": policy_validation_status,
        "risk_category": risk_category,
        "recommended_decision": recommended_decision,
        "key_risk_signals": key_risk_signals,
        "positive_evidence": positive_evidence,
        "missing_or_inconsistent_info": missing_or_inconsistent_info,
        "explanation": explanation,
        "evidence_references": evidence_references,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "disclaimer": DISCLAIMER,
    }
    if extra:
        result.update(extra)
    return result

def risk_category_from_prob(prob: float) -> str:
    if prob < 0.3:
        return "LOW"
    elif prob < 0.7:
        return "MEDIUM"
    else:
        return "HIGH"

def decision_from_prob_and_rules(
    prob: float,
    doc_status: str,
    policy_status: str,
    anomaly_flag: bool,
    thresholds: Dict[str, float]
) -> str:
    """Conservative decision logic with manual review zone."""
    approve_max = thresholds.get("approve_max_prob", 0.3)
    reject_min = thresholds.get("reject_min_prob", 0.7)
    # Hard rules: document or policy failure -> manual review or escalate
    if doc_status == "FAILED" or policy_status == "FAILED":
        if prob >= reject_min:
            return "REJECT_OR_ESCALATE"
        else:
            return "FLAG_FOR_MANUAL_REVIEW"
    if anomaly_flag and prob >= 0.5:
        return "FLAG_FOR_MANUAL_REVIEW"
    if prob < approve_max:
        return "APPROVE"
    elif prob < reject_min:
        return "FLAG_FOR_MANUAL_REVIEW"
    else:
        return "REJECT_OR_ESCALATE"
